5	namespace App\Console\Commands;
6	
7	use App\Models\Category1;
8	use App\Support\XlsxFillColorReader;
9	use AtrioTeam\DigitalHub\Tags\Enum\TagTarget;
10	use AtrioTeam\DigitalHub\Tags\Models\Tag;
11	use AtrioTeam\DigitalHub\Tags\Models\TagCategory;
12	use AtrioTeam\DigitalHub\Tags\Models\TagGroup;
13	use Illuminate\Console\Command;
14	use Illuminate\Support\Facades\DB;
15	use Illuminate\Support\Str;
16	use OpenSpout\Reader\XLSX\Options;
17	use OpenSpout\Reader\XLSX\Reader;
18	
19	/**
20	 * Import dei tag anagrafica dei tessuti dal foglio "Tessuti" del file filtri
21	 * INTERIOR (`INTERIOR - materiali e tessuti filtri.xlsx`).
22	 *
23	 * Il foglio è a colonna singola: righe intestazione di blocco (Tipologia,
24	 * Colori, Proprietà, Categoria, Moodboard, Tipo disegno) seguite dai valori;
25	 * le righe separatore (`____`) e vuote vengono ignorate. Per le righe del
26	 * blocco "Colori" la colonna B ha lo sfondo colorato con lo swatch del colore:
27	 * viene letto (XlsxFillColorReader) e salvato sul tag (`color`, #RRGGBB).
28	 *
29	 * Ogni blocco diventa una TagCategory (identificata dallo slug) dentro il
30	 * gruppo "Filtri Tessuti Indoor" (entity_type=fabric, target=entity, Category1
31	 * Indoor), ogni valore un Tag della categoria. Idempotente: categorie e tag
32	 * esistenti vengono aggiornati.
33	 */
34	class ImportIndoorFiltriTessuti extends Command
35	{
36	    protected $signature = 'app:import-indoor-filtri-tessuti '
37	        . '{--file=storage/app/private/import/indoor/materiali-tessuti/INTERIOR - materiali e tessuti filtri.xlsx} '
38	        . '{--fresh : Svuota i tag delle categorie interessate prima di reimportare}';
39	
40	    protected $description = 'Import dei tag anagrafica tessuti dal file filtri INTERIOR (foglio "Tessuti")';
41	
42	    private const SHEET = 'Tessuti';
43	
44	    /** Colonna con lo sfondo colorato accanto ai valori del blocco "Colori". */
45	    private const COLOR_COLUMN = 'B';
46	
47	    /**
48	     * Intestazioni di blocco (chiave normalizzata) → nome visualizzato della
49	     * TagCategory. Nel foglio compaiono con casing misto (es. "CATEGORIA").
50	     *
51	     * @var array<string, string>
52	     */
53	    private const BLOCKS = [
54	        'tipologia' => 'Tipologia',
55	        'colori' => 'Colori',
56	        'proprietà' => 'Proprietà',
57	        'categoria' => 'Categoria',
58	        'moodboard' => 'Moodboard',
59	        'tipo disegno' => 'Tipo disegno',
60	    ];
61	
62	    public function handle(): int
63	    {
64	        $file = (string) $this->option('file');
65	        if (! is_file($file)) {
66	            $this->error("File non trovato: {$file}");
67	
68	            return self::FAILURE;
69	        }
70	
71	        $blocks = $this->parseSheet($file);
72	        if ($blocks === null) {
73	            $this->error('Foglio "' . self::SHEET . '" non trovato nel file.');
74	
75	            return self::FAILURE;
76	        }
77	
78	        $stats = ['categories' => 0, 'tags' => 0, 'colors' => 0];
79	
80	        DB::transaction(function () use ($blocks, &$stats): void {
81	            $group = $this->resolveGroup();
82	
83	            $categorySort = 0;
84	            foreach ($blocks as $blockName => $values) {
85	                $category = TagCategory::query()->updateOrCreate(
86	                    ['tag_group_id' => $group->id, 'slug' => Str::slug($blockName)],
87	                    ['name' => ['it' => $blockName, 'en' => $blockName], 'sort' => $categorySort++],
88	                );
89	                $stats['categories']++;
90	
91	                if ($this->option('fresh')) {
92	                    Tag::query()->where('tag_category_id', $category->id)->delete();
93	                }
94	
95	                foreach ($values as ['value' => $value, 'color' => $color]) {
96	                    /** @var Tag|null $tag */
97	                    $tag = Tag::query()
98	                        ->where('tag_category_id', $category->id)
99	                        ->where('name->it', $value)
100	                        ->first();
101	
102	                    if ($tag === null) {
103	                        $tag = new Tag();
104	                        $tag->tag_category_id = $category->id;
105	                    }
106	                    $tag->setTranslations('name', ['it' => $value, 'en' => $value]);
107	                    $tag->color = $color;
108	                    $tag->save();
109	                    $stats['tags']++;
110	                    if ($color !== null) {
111	                        $stats['colors']++;
112	                    }
113	                }
114	            }
115	        });
116	
117	        $this->info('Import tag tessuti completato.');
118	        $this->table(
119	            ['Metrica', 'Valore'],
120	            collect($stats)->map(fn ($v, $k): array => [$k, $v])->values()->all(),
121	        );
122	
123	        return self::SUCCESS;
124	    }
125	
126	    /**
127	     * Legge il foglio Tessuti e raggruppa i valori per blocco, con l'eventuale
128	     * colore swatch della riga (sfondo della colonna B, blocco "Colori").
129	     * Ritorna null se il foglio non esiste.
130	     *
131	     * @return array<string, list<array{value: string, color: string|null}>>|null
132	     */
133	    private function parseSheet(string $file): ?array
134	    {
135	        $blocks = null;
136	        $current = null;
137	
138	        $rowColors = (new XlsxFillColorReader())->read($file, self::SHEET, self::COLOR_COLUMN);
139	
140	        // preserva le righe vuote così l'indice del RowIterator coincide con
141	        // il numero di riga reale del foglio (chiave di $rowColors)
142	        $options = new Options();
143	        $options->SHOULD_PRESERVE_EMPTY_ROWS = true;
144	
145	        $reader = new Reader($options);
146	        $reader->open($file);
147	        foreach ($reader->getSheetIterator() as $sheet) {
148	            if ($sheet->getName() !== self::SHEET) {
149	                continue;
150	            }
151	            $blocks = [];
152	
153	            /** @var int $rowNumber */
154	            foreach ($sheet->getRowIterator() as $rowNumber => $row) {
155	                $cell = $row->getCells()[0] ?? null;
156	                $raw = $cell?->getValue();
157	                $value = is_scalar($raw) ? trim((string) $raw) : '';
158	
159	                // righe vuote e separatori (____) tra i gruppi di colori
160	                if ($value === '' || preg_match('/^_+$/', $value) === 1) {
161	                    continue;
162	                }
163	
164	                $blockName = self::BLOCKS[$this->normalize($value)] ?? null;
165	                if ($blockName !== null) {
166	                    $current = $blockName;
167	                    $blocks[$current] ??= [];
168	
169	                    continue;
170	                }
171	
172	                if ($current === null) {
173	                    $this->warn("Valore fuori da ogni blocco, ignorato: {$value}");
174	
175	                    continue;
176	                }
177	
178	                $blocks[$current][] = ['value' => $value, 'color' => $rowColors[$rowNumber] ?? null];
179	            }
180	
181	            break;
182	        }
183	        $reader->close();
184	
185	        return $blocks;
186	    }
187	
188	    /**
189	     * Gruppo tag anagrafica dei tessuti Indoor (creato se assente).
190	     * Fallisce se la Category1 Indoor (slug stabile, il nome può cambiare)
191	     * non esiste.
192	     */
193	    private function resolveGroup(): TagGroup
194	    {
195	        $indoor = Category1::query()->where('slug', 'indoor')->firstOrFail();
196	
197	        return TagGroup::query()
198	            ->where('entity_type', 'fabric')
199	            ->where('target', TagTarget::Entity)
200	            ->where('category_1_id', $indoor->id)
201	            ->first()
202	            ?? TagGroup::query()->create([
203	                'entity_type' => 'fabric',
204	                'target' => TagTarget::Entity,
205	                'category_1_id' => $indoor->id,
206	                'name' => ['it' => 'Filtri Tessuti Interior', 'en' => 'Interior fabric filters'],
207	            ]);
208	    }
209	
210	    private function normalize(string $value): string
211	    {
212	        return trim((string) preg_replace('/\s+/', ' ', mb_strtolower($value)));
213	    }
214	}
